/*
 * landing.c -- lunar landing lane against the real AGC code (yaAGC oracle).
 *
 * Inputs and expected words: tools/oracle/cases/landing.spec / .txt
 * (Luminary099), generated by tools/oracle/cases/gen/gen_landing.py.
 * One P63/P64 guidance pass (RGVGCALC, TTF/8CL + ROOTPSRS, TDISPSET,
 * QUADGUID, AFCCALC), CGCALC, THROTTLE (five throttle regions and the P66
 * FWEIGHT period) and FINDCDUW (gimbal angles and thrust-direction filter
 * outside PNGCS auto).
 *
 * Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md.
 */
#include <stdio.h>

#include "agc/core/assert.h"
#include "agc/core/channels.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/exec/exec.h"
#include "agc/guidance/guidance.h"
#include "agc/lm/landing.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

static agc_mat_t mat_in(const char *t, const char *name)
{
    agc_mat_t m;

    for (int r = 0; r < 3; r++)
    {
        m.row[r] = oracle_in_vec_at(t, name, r);
    }

    return (m);
}

/* The 28-word target block set as `name` (RBRFG, or RBRFG+28 = RAPFG). */
static void target_in(const char *t, const char *name, agc_lm_target_t *g)
{
    const int base = 0;

    for (int c = 0; c < 3; c++)
    {
        g->rfg.c[c] = oracle_in_dp(t, name, base + 2 * c);
        g->vfg.c[c] = oracle_in_dp(t, name, base + 6 + 2 * c);
        g->afg.c[c] = oracle_in_dp(t, name, base + 12 + 2 * c);
    }

    g->vfg_star = oracle_in_dp(t, name, base + 18);
    g->afg_star = oracle_in_dp(t, name, base + 20);
    g->jfg_star = oracle_in_dp(t, name, base + 22);
    g->gain     = oracle_in_dp(t, name, base + 24);
    g->tcgf     = (agc_sp_t) oracle_in(t, name, base + 26);
    g->tcgi     = (agc_sp_t) oracle_in(t, name, base + 27);
}

static void common_in(const char *t)
{
    agc_lm_pad_t  *p = agc_lm_pad();
    agc_lm_ldg_t  *l = agc_lm_ldg();
    agc_guid_lm_t *g = &agc_guid_state()->lm;

    agc_state_init(AGC_VEHICLE_LM);
    (void) agc_exec_init();
    (void) agc_guid_init(AGC_VEHICLE_LM);
    agc_lm_landing_reset();
    target_in(t, "RBRFG", &p->target[0]);
    target_in(t, "RBRFG+28", &p->target[1]); /* RAPFG .. TCGIAPPR */
    p->leadtime = (agc_sp_t) oracle_in(t, "LEADTIME", 0);
    g->mass     = oracle_in_dp(t, "MASS", 0);
    l->wm       = oracle_in_vec(t, "WM");
}

static void guid_pass(const char *t, long tol)
{
    agc_interp_t   ip;
    agc_lm_ldg_t  *l = agc_lm_ldg();
    agc_guid_lm_t *g = &agc_guid_state()->lm;

    common_in(t);
    agc_interp_init(&ip);
    g->r                        = oracle_in_vec(t, "R");
    g->v                        = oracle_in_vec(t, "V");
    g->xnbpip.row[0]            = oracle_in_vec(t, "XNBPIP");
    g->xnbpip.row[2]            = oracle_in_vec(t, "ZNBPIP");
    agc_guid_state()->avg.gdt_2 = oracle_in_vec(t, "GDT/2");
    l->land                     = oracle_in_vec(t, "LAND");
    l->cg                       = mat_in(t, "CG");
    l->ttf_8                    = oracle_in_dp(t, "TTF/8", 0);
    l->ttf_8_hi                 = (agc_sp_t) oracle_in(t, "TTF/8", 0);
    l->wchphase                 = (agc_sp_t) oracle_in(t, "WCHPHASE", 0);
    l->flpass0                  = (agc_sp_t) oracle_in(t, "FLPASS0", 0);
    (void) agc_lm_rgvgcalc(&ip);
    (void) agc_lm_ttf8cl(&ip);
    (void) agc_lm_quadguid(&ip);
    oracle_require_ok(t, "CGCALC");
    oracle_cmp_vec(t, "ANGTERM", l->angterm, oracle_out_vec(t, "ANGTERM"), tol);
    oracle_cmp_vec(t, "VGU", l->vgu, oracle_out_vec(t, "VGU"), tol);
    (void) oracle_cmp(t, "VHORIZ", l->vhoriz, oracle_out_dp(t, "VHORIZ"), tol);
    oracle_cmp_vec(t, "RGU", l->rgu, oracle_out_vec(t, "RGU"), tol);
    (void) oracle_cmp(t, "RANGEDSP", l->rangedsp,
                      oracle_out_dp(t, "RANGEDSP"), tol);
    (void) oracle_cmp(t, "LOOKANGL", l->lookangl,
                      oracle_out_sp(t, "LOOKANGL"), 0);
    /* ROOTPSRS stops at |DX| <= TTF/8 * 2^-7: last-pass rounding moves the
     * root by a few hundred LSB. TTFDISP = 8 * high word of a DAS result
     * the AGC leaves sign-disagreeing (F9): one high-word LSB = 8.       */
    (void) oracle_cmp(t, "TTF/8", l->ttf_8, oracle_out_dp(t, "TTF/8"), 0);
    (void) oracle_cmp(t, "TTFDISP", l->ttfdisp, oracle_out_dp(t, "TTFDISP"),
                      0);
    (void) oracle_cmp(t, "TREDES", l->tredes, oracle_out_sp(t, "TREDES"), 0);
    /* QUADGUID coefficients: the AGC stores them as single words over
     * stale low words of the push list (guidance.c DEVIATION).           */
    oracle_cmp_vec(t, "UNFC/2", l->unfc_2, oracle_out_vec(t, "UNFC/2"), 128);
    (void) oracle_cmp(t, "/AFC/", l->afc, oracle_out_dp(t, "/AFC/"), 128);
    (void) oracle_cmp(t, "FLPASS0", l->flpass0, oracle_out_sp(t, "FLPASS0"),
                      0);
    (void) oracle_cmp(t, "WCHPHOLD", l->wchphold,
                      oracle_out_sp(t, "WCHPHOLD"), 0);
}

static void cgcalc(const char *t, long tol)
{
    agc_interp_t  ip;
    agc_lm_ldg_t *l = agc_lm_ldg();

    common_in(t);
    agc_interp_init(&ip);
    agc_guid_state()->lm.r = oracle_in_vec(t, "R");
    l->land                = oracle_in_vec(t, "LAND");
    l->angterm             = oracle_in_vec(t, "ANGTERM");
    l->ttf_8               = oracle_in_dp(t, "TTF/8", 0);
    l->ttf_8_hi            = (agc_sp_t) oracle_in(t, "TTF/8", 0);
    l->wchphase            = (agc_sp_t) oracle_in(t, "WCHPHASE", 0);
    l->cg                  = mat_in(t, "CG");
    (void) agc_lm_cgcalc(&ip);
    oracle_require_ok(t, "EXTLOGIC");

    for (int r = 0; r < 3; r++)
    {
        char n[16];
        char w[16];

        (void) snprintf(n, sizeof n, (r == 0) ? "CG" : "CG+%d", 6 * r);
        (void) snprintf(w, sizeof w, "CG[%d]", r);
        oracle_cmp_vec(t, w, l->cg.row[r], oracle_out_vec(t, n), tol);
    }
}

static void throttle(const char *t)
{
    agc_lm_ldg_t *l = agc_lm_ldg();
    agc_lm_thr_t *h = agc_lm_thr();

    common_in(t);
    agc_lm_pad()->lowcrit       = (agc_sp_t) oracle_in(t, "LOWCRIT", 0);
    agc_lm_pad()->highcrit      = (agc_sp_t) oracle_in(t, "LOWCRIT", 1);
    agc_guid_state()->lm.abdelv = (agc_sp_t) oracle_in(t, "ABDELV", 0);
    l->afc                      = oracle_in_dp(t, "/AFC/", 0);
    l->thistpip                 = oracle_in_dp(t, "THISTPIP", 0);
    h->tthrot                   = (agc_sp_t) oracle_in(t, "TTHROT", 0);
    h->fweight                  = oracle_in_dp(t, "FWEIGHT", 0);
    h->fcold                    = (agc_sp_t) oracle_in(t, "FCOLD", 0);
    agc_erase_set_modreg((agc_sp_t) oracle_in(t, "MODREG", 0));
    agc_erase_set_piptime(oracle_in_dp(t, "PIPTIME", 0));
    /* TIME1 as the AGC read it at DOIT (the emulated counter ticks once
     * while THROTTLE runs; the AGC stored that reading in TTHROT).       */
    agc_time_set_cs((uint32_t) oracle_out_sp(t, "TTHROT"));
    (void) agc_lm_throttle();
    oracle_require_ok(t, "ENDOFJOB");
    (void) oracle_cmp(t, "FP", h->fp, oracle_out_dp(t, "FP"), 0);
    (void) oracle_cmp(t, "FC", agc_dp_high(h->fc), oracle_out_sp(t, "FC"), 0);
    (void) oracle_cmp(t, "FCODD", h->fcodd, oracle_out_dp(t, "FCODD"), 0);
    (void) oracle_cmp(t, "FCOLD", h->fcold, oracle_out_sp(t, "FCOLD"), 0);
    (void) oracle_cmp(t, "PIF", h->pif, oracle_out_dp(t, "PIF"), 0);
    (void) oracle_cmp(t, "PIFPSET", h->pifpset, oracle_out_sp(t, "PIFPSET"), 0);
    /* F9: PIF = FC - FP by DAS is left sign-disagreeing by the AGC, which
     * then uses its high word alone (CA PIF, MP PIF).                    */
    oracle_cmp_known(t, "PSEUDO55", h->pseudo55, oracle_out_sp(t, "PSEUDO55"),
                     0, "F9");
    oracle_cmp_known(t, "THRUST", agc_erase_thrust(),
                     oracle_out_sp(t, "THRUST"), 0, "F9");
    oracle_cmp_known(t, "FWEIGHT", h->fweight, oracle_out_dp(t, "FWEIGHT"), 0,
                     "F9");
}

static void findcduw(const char *t, long tol)
{
    agc_interp_t   ip;
    agc_guid_lm_t *g = &agc_guid_state()->lm;
    agc_vec_t      unfc;

    common_in(t);
    agc_interp_init(&ip);
    (void) agc_chan_set_input(AGC_CHAN_CHAN30, 037777); /* yaAGC power-up */
    (void) agc_chan_set_input(AGC_CHAN_CHAN31, 077777);
    agc_lm_initcduw();
    agc_lm_ldg()->unwc_2 = oracle_in_vec(t, "UNWC/2");
    g->xnbpip.row[0]     = oracle_in_vec(t, "XNBPIP");
    g->xnbpip.row[2]     = oracle_in_vec(t, "ZNBPIP");
    agc_erase_set_delv(oracle_in_vec(t, "DELV"));
    agc_erase_set_cdux(oracle_in_raw(t, "CDUX", 0));
    agc_erase_set_cduy(oracle_in_raw(t, "CDUX", 1));
    agc_erase_set_cduz(oracle_in_raw(t, "CDUX", 2));
    unfc.c[0] = oracle_in_dp(t, "MPAC", 0);
    unfc.c[1] = oracle_in_dp(t, "MPAC", 3);
    unfc.c[2] = oracle_in_dp(t, "MPAC", 5);
    (void) agc_lm_findcduw(&ip, unfc);
    oracle_require_ok(t, "DSPLY81");

    for (int k = 0; k < 3; k++)
    {
        char n[16];

        (void) snprintf(n, sizeof n, (k == 0) ? "CPHI" : "CPHI+%d", k);
        (void) oracle_cmp(t, n, (long) (int16_t) (agc_erase_thetad(k) << 1) / 2,
                          oracle_out_sp(t, n), tol);
    }
}

int main(void)
{
    if (!oracle_load("landing"))
    {
        (void) printf("oracle_landing: SKIP (case files not found)\n");

        return (0);
    }

    guid_pass("guid_brak_a", 4);
    guid_pass("guid_brak_b", 4);
    guid_pass("guid_appr", 4);
    cgcalc("cgcalc_brak", 0);
    cgcalc("cgcalc_appr", 0);
    throttle("throt_mid");
    throttle("throt_old");
    throttle("throt_up");
    throttle("throt_hold");
    throttle("throt_down");
    throttle("throt_p66");
    findcduw("findcduw_a", 1);
    findcduw("findcduw_b", 1);

    return (oracle_finish("oracle_landing"));
}
